function x = robustSolve(A, b)
    if det(A) ~= 0
        x = A\b;
    else
        error('Singular matrix');
    end
end

function x = solve(A, b)
    [m, n] = size(A);
    if m == n
        x = A\b;
    else
        x = inv(A)\b;   % <-- fallback for rectangular A
    end
end

function x = doseSolve(A, b)
