function [beta, R2] = fitPoly(x, y, degree)
    A = [];
    for d = degree:-1:1
        A = [A, x(:).^d];
    end
    beta = A\y(:);
    y_fit = A*beta;
    R2 = 1 - sum((y(:)-y_fit).^2)/sum((y(:)-mean(y)).^2);
end

